args.new_string:
/** 摘掉某个查询参数后重新拼路径；解析失败或本来就没有则原样返回。 */
export function stripQueryParam(reqUrl, name) {
  let u;
  try { u = new URL(reqUrl ?? '/', 'http://dsh.invalid'); } catch { return reqUrl; }
  if (!u.searchParams.has(name)) return reqUrl;
  u.searchParams.delete(name);
  return `${u.pathname}${u.search}`;
}

// ---------- 首登参数保留（2026-09-06） ----------
// 用户带 ?dsh-layout=desktop/mobile（或任何业务参数）首次打开公网地址时，登录链路
// 「密码页 → POST /pocket-login → 302 → 握手过渡页 → meta refresh 回 /」原本会把查询串
// 一路丢光：客户端 layout-mode.mjs 只有页面真正加载后才能读 ?dsh-layout=，而首登时它
// 还没机会运行、localStorage 也还是空的 → 参数静默失效。下面两个函数把「非 pocket 自用」
// 的参数挑出来（URLSearchParams 重新编码，可安全内插进 HTML 属性与 Location 头），
// 让登录链路的每一跳都带着走。
export function preservedQuery(reqUrl) {
  let u;
  try { u = new URL(reqUrl ?? '/', 'http://dsh.invalid'); } catch { return ''; }
  const p = new URLSearchParams();
  for (const [k, v] of u.searchParams) {
    if (k === 'token' || k === 'dsh-pocket-auth' || k === HANDSHAKE_RETRY_PARAM || k.startsWith('dsh-desktop-')) continue;
    p.append(k, v);
  }
  const s = p.toString();
  return s ? `?${s}` : '';
}

/** 过渡页回跳目标：原请求去掉 pocket 自用参数后的干净 URL；解析失败或可疑目标兜底 '/'。 */
export function handshakeRefreshTarget(reqUrl) {
  let u;
  try { u = new URL(reqUrl ?? '/', 'http://dsh.invalid'); } catch { return '/'; }
  const target = u.pathname + preservedQuery(reqUrl);
  // 只允许站内相对目标：拒绝协议相对 //host 与反斜杠混淆（meta refresh 开放重定向防护）
  if (!target.startsWith('/') || target.startsWith('//') || target.includes('\\')) return '/';
  return target;
}

